<?php require __DIR__.'/../config/functions.php'; require_admin(); $db=get_db(); if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $map=array('chat'=>'agnes-2.0-flash','image'=>'agnes-image-2.1-flash','video'=>'agnes-video-v2.0'); $type=$_POST['model_type']; $db->prepare('INSERT INTO api_configs(model_type,model_name,api_key,base_url,enabled,created_at) VALUES(?,?,?,?,1,NOW())')->execute(array($type,$map[$type],encrypt_secret($_POST['api_key']),$_POST['base_url'])); } $list=$db->query('SELECT * FROM api_configs ORDER BY id DESC')->fetchAll(); page_header('API配置'); ?><form class="card" method="post"><h2>模型API配置中心</h2><input type="hidden" name="csrf" value="<?php echo csrf_token();?>"><select name="model_type"><option value="chat">agnes-2.0-flash 对话</option><option value="image">agnes-image-2.1-flash 图片</option><option value="video">agnes-video-v2.0 视频</option></select><input name="api_key" placeholder="API Key（加密存储）"><input name="base_url" placeholder="API Endpoint"><button>保存</button><p>文档：<a target="_blank" href="https://agnes-ai.com/doc/agnes-20-flash">对话模型</a><a target="_blank" href="https://agnes-ai.com/doc/agnes-image-21-flash">图片模型</a><a target="_blank" href="https://agnes-ai.com/doc/agnes-video-v20">视频模型</a></p></form><table><tr><th>模型</th><th>地址</th><th>Key</th><th>连通性</th></tr><?php foreach($list as $r) echo '<tr><td>'.esc($r['model_name']).'</td><td>'.esc($r['base_url']).'</td><td>***'.esc(substr(decrypt_secret($r['api_key']),-4)).'</td><td><a href="/api/test_model.php?type='.esc($r['model_type']).'">测试</a></td></tr>'; ?></table><?php page_footer(); ?>
